import logging
from inspect import ismethod
from selenium.common.exceptions import StaleElementReferenceException


def choose_selector_way(func):
    def choose_way_select_element(self, selector, by="css"):
        select_element_script = None
        if by == "css":
            select_element_script = "document.querySelector(\'{}\')".format(selector)
        elif by == 'id':
            select_element_script = "document.getElementById(\'{}\')".format(selector)
        return func(self, select_element_script, by)

    return choose_way_select_element


def deprecated(cls):
    class DeprecatedCls(object):
        DEPRECATION_MESSAGE = "{} is deprecated, pls use taf.selenium.sc for substitute"

        def __init__(self, *args, **kwargs):
            self.oInstance = cls(*args, **kwargs)

        def __getattribute__(self, name):
            try:
                attr = super(DeprecatedCls, self).__getattribute__(name)
            except AttributeError:
                pass
            else:
                return attr
            attr = self.oInstance.__getattribute__(name)
            if ismethod(attr):
                logging.warning(self.DEPRECATION_MESSAGE.format(attr.__name__))
                return attr

    return DeprecatedCls


def raise_stale_element_reference_exception(retry_times, msg):
    if not retry_times:
        raise StaleElementReferenceException(msg)


def catch_target_exception(self, func, retry_times, *args, **kwargs):
    while retry_times:
        retry_times -= 1
        try:
            return func(self, *args, **kwargs)
        except StaleElementReferenceException as msg:
            raise_stale_element_reference_exception(retry_times, msg)


def wait_for_operation_success(retry_times):
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            return catch_target_exception(self, func, retry_times, *args, **kwargs)

        return wrapper

    return decorator
